-- ----------------------------
-- Table structure for f_t_measure_analysis_data
-- ----------------------------
DROP TABLE IF EXISTS `f_t_measure_analysis_data`;
CREATE TABLE `f_t_measure_analysis_data`  (
  `id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '分析数据id',
  `analysis_number` int(11) NULL DEFAULT NULL COMMENT '分析编号',
  `analysis_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '分析名称',
  `task_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '测量任务id',
  `sample_key` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '样品id',
  `measure_data_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '测量数据id',
  `data_version` int(20) NULL DEFAULT NULL COMMENT '版本号',
  `analysis_param` json NULL COMMENT '分析参数',
  `analysis_result` json NULL COMMENT '分析结果',
  `analysis_type` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '变换类型',
  `gauge_point` json NULL COMMENT '标记点',
  `peak` json NULL COMMENT '峰',
  `grain` json NULL COMMENT '谷',
  `color` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '颜色',
  `analysis_data_image` longblob NULL COMMENT '分析数据图像',
  `is_save` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '是否保存(0.保存,1.不保存)',
  `is_delete` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '是否删除(0.正常,1.已删除)',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '分析数据表' ROW_FORMAT = DYNAMIC;

