DROP TABLE IF EXISTS `f_t_measure_data`;
CREATE TABLE `f_t_measure_data`  (
  `id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '测量数据id',
  `task_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '测量任务id',
  `serial_number` int(11) NULL DEFAULT 0 COMMENT '序号',
  `sample_key` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '样品Key',
  `instrument_data` json NULL COMMENT '仪器数据',
  `original_calculation_data` json NULL COMMENT '原始计算数据',
  `measurement_start_time` datetime NULL DEFAULT NULL COMMENT '测量开始时间',
  `measurement_end_time` datetime NULL DEFAULT NULL COMMENT '测量结束时间',
  `gauge_point` json NULL COMMENT '标记点',
  `peak` json NULL COMMENT '峰',
  `grain` json NULL COMMENT '谷',
  `sampling_time` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '采样时间',
  `data_image` longblob NULL COMMENT '数据图像',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `is_save` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '是否保存',
  `is_delete` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '是否删除',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_measurement_start_time`(`measurement_start_time`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '测量数据表' ROW_FORMAT = DYNAMIC;

