-- Table structure for f_t_measure_method
-- ----------------------------
DROP TABLE IF EXISTS `f_t_measure_method`;
CREATE TABLE `f_t_measure_method`  (
  `id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '方法id',
  `preprocess_key` varchar(768) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '前处理Key',
  `multiple_calculation_formula_key` varchar(768) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '多个计算公式Key',
  `project_item_key` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '所属项目Key(当选用的是公共方法则项目key为空)',
  `method_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '方法名称',
  `measurement_type` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '测量类型',
  `measurement_param_info` json NULL COMMENT '测量参数信息',
  `is_sharing_method` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '是否共享方法(0.否 1.是)',
  `method_create_time` datetime NULL DEFAULT NULL COMMENT '方法创建时间',
  `method_creator` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '方法创建人',
  `method_use_time` datetime NULL DEFAULT NULL COMMENT '方法使用时间',
  `is_draft` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '是否草稿(0.不是草稿 1.是草稿)',
  `use_state` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '使用状态',
  `field5` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '预留字段5',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '测量方法表' ROW_FORMAT = DYNAMIC;

