INSERT INTO `f_t_measure_method` VALUES ('176fef6e5eb9b47ad4382c1f7780a671', NULL, NULL, 'default', '默认方法', '光度测量', '{\"qcParams\": [], \"energyLamp\": \"\", \"luminosity\": \"1\", \"waveLength\": [\"660.5\"], \"approxParams\": [], \"responseTime\": \"0.5\", \"resultParams\": [], \"timeInterval\": \"3\", \"luminosityName\": \"Abs\", \"repetitionTime\": \"2\", \"repetitionPattern\": \"不重复\", \"sampleInputParams\": [{\"unit\": \"Abs\", \"paramName\": \"660.5\", \"resultIdentity\": \"A\"}], \"spectralBandwidth\": \"2\", \"statisticalContent\": [\"平均值\"], \"changeLampWaveLength\": \"361\"}', NULL, '2025-08-19 11:14:35', 'admin', '2025-09-16 08:37:03', NULL, NULL, NULL);
INSERT INTO `f_t_measure_method` VALUES ('408b118ef86fc07ba7f4d959acbf120a', NULL, NULL, 'default', '默认方法', '定量测定', '{\"gain\": 1, \"qcParams\": [], \"curveType\": \"1\", \"energyLamp\": \"0\", \"repeatMode\": \"不重复\", \"waveLength\": [\"660\"], \"approxParams\": [], \"equationType\": \"f_C\", \"responseTime\": \"0.5\", \"resultParams\": [], \"timeInterval\": \"0\", \"curveTypeName\": \"一次曲线\", \"samplePoolWay\": \"1\", \"energyLampName\": \"钨灯\", \"coefficientMode\": \"standard\", \"differentialMode\": \"no_differential\", \"equationTypeName\": \"Abs=f(C)\", \"waveLengthParams\": [\"1\"], \"sampleInputParams\": [], \"spectralBandwidth\": \"2\", \"waveLengthFormula\": \"Abs=660Abs\", \"coefficientModeName\": \"标准曲线法\", \"changeLampWaveLength\": \"361\", \"differentialModeName\": \"不微分\"}', NULL, '2025-09-16 10:48:09', 'admin', NULL, NULL, NULL, NULL);
INSERT INTO `f_t_measure_method` VALUES ('5ea5ed9f0a10668500060669936db3a2', NULL, NULL, 'default', '默认方法', '时间扫描', '{\"gain\": 3, \"scanTime\": \"60\", \"scanUnit\": \"1\", \"energyLamp\": \"1\", \"luminosity\": \"1\", \"waveLength\": \"660\", \"totalNumber\": \"60\", \"intervalTime\": \"1\", \"responseTime\": \"0.5\", \"multiPoolMode\": \"0\", \"spectralBandwidth\": \"2\", \"changeLampWaveLength\": \"361\"}', NULL, '2025-09-15 08:47:55', 'admin', '2025-09-17 13:55:13', NULL, NULL, NULL);
INSERT INTO `f_t_measure_method` VALUES ('ea55d34f408b2e4cdceda26c52e38e25', NULL, NULL, 'default', '默认方法', '光谱扫描', '{\"gain\": 3, \"scanSpeed\": \"1\", \"energyLamp\": \"1\", \"luminosity\": \"1\", \"timeInterval\": \"1\", \"endWaveLength\": \"190\", \"repetitionTime\": \"2\", \"startWaveLength\": \"900\", \"ladderCorrection\": true, \"repetitionPattern\": \"不重复\", \"spectralBandwidth\": \"2\", \"waveLengthInterval\": \"1\", \"changeLampWaveLength\": \"361\"}', NULL, '2025-09-14 13:43:11', 'admin', '2025-09-17 13:57:31', NULL, NULL, NULL);

