  `dilution_ratio` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '稀释倍数',
  `sample_volume` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '取样量',
  `constant_volume` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '定容体积',
  `normal_concentration` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '标准浓度',
  `sample_location` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '样品位置',
  `sample_description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '样品描述',
  `input_data` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '输入数据',
  `color` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '颜色',
  `heads` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '表头信息',
  `new_col_data` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '新的列数据',
  `data_bulk` bigint(36) NULL DEFAULT NULL COMMENT '数据数量',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '样品信息表' ROW_FORMAT = DYNAMIC;

